{
  "fact_1": {
    "topic": "课程开场兑现承诺与机器视角",
    "claim": "讲师在课前兑现了承诺，有人将在下课之前赢得一副Google Cardboard虚拟现实眼镜；讲师随后让听众把自己当作一台机器，除了听众告诉他的内容之外什么都不知道。",
    "evidence": [2, 3, 4, 5, 6, 7, 8, 10, 11, 12, 13, 14, 15],
    "attribution": "source",
    "importance": "support"
  },
  "fact_2": {
    "topic": "命令式知识的定义",
    "claim": "命令式知识是配方、操作指南或步骤序列；如果讲师作为机器遵循这些步骤，理论上就能得出结论。",
    "evidence": [23, 24, 25, 26, 27, 31, 32, 33, 34, 35, 36, 37, 38, 39],
    "attribution": "source",
    "importance": "core"
  },
  "fact_3": {
    "topic": "用Python随机抽取获奖者的步骤",
    "claim": "讲师打开本课程使用的Anaconda IDE，按照步骤在第一个和最后一个回应者之间随机选择一个数字，并实际使用Python的random.randint在16到272之间抽取随机数，然后在回应者名单中找到对应的人。",
    "evidence": [44, 49, 50, 55, 56, 57, 58, 59, 60, 61, 62, 80, 81, 82, 89, 90, 91, 96, 97, 98, 99, 100, 101, 102, 103, 104, 105, 106],
    "attribution": "source",
    "importance": "support"
  },
  "fact_4": {
    "topic": "用编程避免人为偏差并练习Python",
    "claim": "讲师指出，如果自己选择随机数可能会因为例如喜欢数字8而产生偏差，因此使用计算机或编程来完成这个简单任务；他鼓励尽可能使用Python来获得练习。",
    "evidence": [63, 64, 65, 66, 67, 68, 69, 70, 71, 72, 73, 74, 120, 121, 122, 123],
    "attribution": "source",
    "importance": "support"
  },
  "fact_5": {
    "topic": "声明式知识与命令式知识的数值示例对比",
    "claim": "声明式知识的例子是：数字x的平方根是y，使得y乘以y等于x；这是一个事实陈述，但计算机不知道如何处理它，而计算机知道如何遵循配方。",
    "evidence": [128, 129, 130, 131, 132, 133, 134, 135, 136, 137, 138, 139, 140, 141, 142, 143, 144, 145],
    "attribution": "source",
    "importance": "core"
  },
  "fact_6": {
    "topic": "求平方根的算法步骤",
    "claim": "一个著名的求数字x平方根的算法是：从猜测值g开始，计算g乘以g，如果g乘以g足够接近x则停止并说g是答案；如果不够接近，则通过平均g和x除以g来产生新猜测，然后用新猜测重复整个过程。",
    "evidence": [146, 147, 148, 149, 150, 151, 152, 153, 154, 155, 156, 157, 158, 159, 160, 161, 162, 163, 164, 165, 166, 167, 168, 169, 170, 171, 172, 173, 174, 175, 176, 177, 178, 179, 180, 181, 182, 183, 184, 185, 186, 187],
    "attribution": "source",
    "importance": "core"
  },
  "fact_7": {
    "topic": "配方的三个组成部分",
    "claim": "命令式知识中的配方有三个部分：简单的步骤序列（该例中有四步）、控制流（包括做出决定和重复某些步骤）以及停止的方式；在求平方根的例子中，停止方式是决定已经足够接近，接近程度可以是0.01、0.001等由人选择的值。",
    "evidence": [194, 195, 196, 197, 198, 199, 200, 201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219, 220, 221, 222, 223, 224],
    "attribution": "source",
    "importance": "core"
  },
  "fact_8": {
    "topic": "算法与课程主题",
    "claim": "在计算机科学术语中，这种配方就是算法，这也是本课程将要学习的内容；课程涉及计算机，并希望将配方捕获到计算机这一机械过程中。",
    "evidence": [225, 226, 227, 228, 229, 230, 231, 232, 233, 234, 235],
    "attribution": "source",
    "importance": "core"
  },
  "fact_9": {
    "topic": "固定程序计算机及其局限",
    "claim": "历史上最初有固定程序计算机，例如只懂加、减、乘、除的旧式计算器；它只能做这一件事，不能绘图、上网或发邮件，若要执行另一项任务就必须制造另一台完全独立的固定程序计算机。",
    "evidence": [236, 237, 238, 239, 240, 241, 242, 243, 244, 245, 246, 247, 248, 249, 250, 251, 252, 253, 254, 255, 256, 257, 258, 259, 260, 261, 262, 263, 264, 265, 266, 267],
    "attribution": "source",
    "importance": "core"
  },
  "fact_10": {
    "topic": "存储程序计算机",
    "claim": "存储程序计算机可以存储一串指令并执行这串指令，还可以改变指令序列并执行不同的指令序列，从而在同一台机器上完成不同任务；这就是如今我们所知的计算机。",
    "evidence": [268, 269, 270, 271, 272, 273, 274, 275, 276, 277, 278, 279, 280, 281, 282],
    "attribution": "source",
    "importance": "core"
  },
  "fact_11": {
    "topic": "基本机器架构的组成部分",
    "claim": "每台计算机核心的基本机器架构包含四个主要部分：内存、输入输出、ALU和控制单元；ALU执行加法、减法等非常原始的操作，内存包含数据和指令序列。",
    "evidence": [288, 289, 290, 291, 292, 293, 294, 295, 296, 297, 298, 299, 300, 301, 302, 303, 304, 305, 306, 307, 308, 309],
    "attribution": "source",
    "importance": "core"
  },
  "fact_12": {
    "topic": "控制单元与程序计数器的执行流程",
    "claim": "控制单元包含一个程序计数器；加载指令序列时，程序计数器从第一条指令开始，取出指令并发送给ALU，ALU可能从内存取数据、执行操作并将数据存回内存，然后程序计数器增加1，线性地逐条执行下一条指令；某条特定指令可能执行测试，例如判断某个值是否大于、等于或等于另一个值。",
    "evidence": [310, 311, 312, 313, 314, 315, 316, 317, 318, 319, 320, 321, 322, 323, 324, 325, 326, 327, 328, 329, 330, 331, 332, 333, 334, 335, 336, 337, 338, 339, 340, 341, 342, 343, 344, 345, 346, 347, 348],
    "attribution": "source",
    "importance": "core"
  }
}
